SELECT COUNT(*) FROM biz_training_session
 WHERE deleted = FALSE
   AND lecturer_id = #{lecturerId}
   AND session_state IN
   #{s}

SELECT ROUND(AVG(f.score)::NUMERIC, 1)
  FROM dtl_training_feedback f
  JOIN biz_training_session s ON s.id = f.session_id AND s.deleted = FALSE
 WHERE f.deleted = FALSE
   AND s.lecturer_id = #{lecturerId}
   AND f.session_id = #{sessionId}
